import React from 'react';
import classNames from 'classnames';
import * as styles from './Subline.module.scss';

interface Props {
  theme?: {
    fontSize: {
      small: number;
      big: number;
    };
    colors: {
      white: string;
      grey: {
        light: string;
      };
    };
  };
  sectionTitle?: string;
  light?: boolean;
  children?: React.ReactNode;
}

const Subline: React.FC<Props> = ({ theme, sectionTitle, light, children }) => {
  // Default values if theme is not provided
  const defaultTheme = {
    fontSize: { small: 1, big: 1.5 },
    colors: { white: '#ffffff', grey: { light: '#eee' } }
  };
  
  const currentTheme = theme || defaultTheme;
  
  const styleVars: React.CSSProperties = {
    // Set font size from theme
    ['--subline-font-size' as any]: currentTheme.fontSize.small,
    // Set light color from theme if needed
    ...(light && { ['--subline-light-color' as any]: `rgba(255,255,255,0.7)` })
  };

  return (
    <div
      className={classNames(
        styles.subline,
        { [styles.light]: light },
        { [styles.sectionTitle]: sectionTitle }
      )}
      style={styleVars}
    >
      {children}
    </div>
  );
};

export default Subline;
