import React, { PropsWithChildren } from 'react';
import config from '../../config/site-config';
import { Link } from 'gatsby';
import { Theme } from '../../config/theme';
import Nav from './Nav';
import { Property } from 'csstype';
import classNames from 'classnames';
import * as styles from './Header.module.scss';

interface Props {
  banner?: string;
  theme?: Theme;
}

const Header = (props: PropsWithChildren<Props>) => {
  const styleVars: React.CSSProperties = {
    ['--header-title-font-family' as any]: props.theme?.fontFamily.heading,
  };

  return (
    <header 
      className={styles.headerWrapper} 
      style={{ background: props.banner || config.defaultBg }}
    >
      <div 
        className={classNames(
          styles.content,
          styles.contentJustifySpaceBetween
        )}
        style={styleVars}
      >
        <div>
          <span className={styles.headerTitle}>Jesús Quintana</span>
          <br />
          <Link to="/">{config.siteTitle}</Link>
        </div>
        <Nav />
      </div>
      <br />
      {props.children && (
        <div 
          className={classNames(
            styles.content,
            styles.contentColumn
          )}
        >
          {props.children}
        </div>
      )}
    </header>
  );
};

export default Header;
